fn is_amount(t: Str) -> Bool {
  if t.is_empty() {
    return false
  }
  let digits = t.chars().all(fn(c) => "0123456789".contains(c))
  if not digits {
    return false
  }
  return t.to_int().unwrap_or(0) > 0
}

pub fn ledger(ops: List[Str]) -> Result[Map[Str, Int], Str] {
  var bal: Map[Str, Int] = Map {}
  for op in ops {
    let parts = op.split(" ")
    let kind = parts.get_or(0, "")
    if kind == "open" and parts.len() == 2 {
      let name = parts.get_or(1, "")
      if name == "" {
        return Err("bad op")
      }
      if bal.has(name) {
        return Err("exists " + name)
      }
      bal = bal.set(name, 0)
    } else if (kind == "dep" or kind == "wd") and parts.len() == 3 {
      let name = parts.get_or(1, "")
      let amt_txt = parts.get_or(2, "")
      if name == "" or not is_amount(amt_txt) {
        return Err("bad op")
      }
      let amt = amt_txt.to_int().unwrap_or(0)
      if not bal.has(name) {
        return Err("unknown " + name)
      }
      let cur = bal.get(name).unwrap_or(0)
      if kind == "dep" {
        bal = bal.set(name, cur + amt)
      } else {
        if cur < amt {
          return Err("insufficient " + name)
        }
        bal = bal.set(name, cur - amt)
      }
    } else if kind == "move" and parts.len() == 4 {
      let src = parts.get_or(1, "")
      let dst = parts.get_or(2, "")
      let amt_txt = parts.get_or(3, "")
      if src == "" or dst == "" or not is_amount(amt_txt) {
        return Err("bad op")
      }
      let amt = amt_txt.to_int().unwrap_or(0)
      if not bal.has(src) {
        return Err("unknown " + src)
      }
      if not bal.has(dst) {
        return Err("unknown " + dst)
      }
      let cur = bal.get(src).unwrap_or(0)
      if cur < amt {
        return Err("insufficient " + src)
      }
      bal = bal.set(src, cur - amt)
      bal = bal.set(dst, bal.get(dst).unwrap_or(0) + amt)
    } else {
      return Err("bad op")
    }
  }
  return Ok(bal)
}
